/**
 * Firestore document shapes. See docs/DATA_MODEL.md for relationships and indexes.
 * All timestamps are ISO-8601 UTC strings generated by the API server.
 */
import type { Permission, RoleId } from './permissions';
import type { AuditActor } from './types';

export interface Timestamps {
  createdAt: string;
  updatedAt: string;
}

// ─── Access ──────────────────────────────────────────────────────────────────

export type AccountStatus = 'active' | 'disabled';

export interface UserDoc extends Timestamps {
  id: string; // Firebase Auth uid
  email: string;
  displayName: string;
  role: RoleId;
  status: AccountStatus;
  phone?: string;
  department?: string;
  branchId?: string;
  isDemo?: boolean;
  photo?: MediaRef;
}

export interface RoleDoc {
  id: RoleId;
  label: string;
  permissions: Permission[];
  updatedAt: string;
  updatedBy?: string;
}

export interface LoginActivityDoc {
  id: string;
  uid: string;
  event: 'login' | 'logout';
  at: string;
  ip?: string;
  userAgent?: string;
}

// ─── Patients & doctors ──────────────────────────────────────────────────────

export type Gender = 'male' | 'female' | 'other';

export interface PatientDoc extends Timestamps {
  id: string;
  mrNumber: string;
  name: string;
  guardianName?: string;
  guardianRelation?: 'father' | 'husband' | 'other';
  dateOfBirth?: string;
  ageYears?: number;
  gender: Gender;
  mobile: string;
  alternateMobile?: string;
  cnic?: string;
  email?: string;
  address: {
    province?: string;
    division?: string;
    district?: string;
    tehsil?: string;
    unionCouncil?: string;
    line?: string;
  };
  referringDoctorId?: string;
  branchId?: string;
  collectionCenterId?: string;
  sampleCollectionLocation?: string;
  panelId?: string;
  category?: string;
  notes?: string;
  attachments: Array<{ path: string; name: string; contentType: string; uploadedAt: string }>;
  status: 'active' | 'archived';
  searchTokens: string[];
  createdBy: AuditActor;
  isDemo?: boolean;
}

export interface DoctorDoc extends Timestamps {
  id: string;
  name: string;
  specialization?: string;
  qualification?: string;
  phone?: string;
  email?: string;
  clinic?: string;
  address?: string;
  commission?: { type: 'none' | 'percent' | 'fixed'; value: number };
  status: 'active' | 'inactive';
  photo?: MediaRef;
  searchTokens: string[];
}

// ─── Catalogue ───────────────────────────────────────────────────────────────

export interface TestCategoryDoc {
  id: string;
  name: string;
  sortOrder: number;
  active: boolean;
}

/**
 * A reference range entry. Ranges are NEVER invented by the software: they are
 * entered by laboratory staff and must be approved by a user holding
 * `tests.approveRanges` before they are used for flagging or printed.
 */
export interface ReferenceRange {
  id: string;
  gender: Gender | 'any';
  ageMinYears?: number;
  ageMaxYears?: number;
  low?: number;
  high?: number;
  /** Free text for qualitative ranges, e.g. "Negative". */
  text?: string;
  criticalLow?: number;
  criticalHigh?: number;
  status: 'draft' | 'approved';
  approvedBy?: AuditActor;
  approvedAt?: string;
}

export type ResultInputType = 'numeric' | 'text' | 'select';

export interface TestParameter {
  id: string;
  name: string;
  code?: string;
  unit?: string;
  inputType: ResultInputType;
  /** For `select` inputs, e.g. ["Positive", "Negative"]. */
  options?: string[];
  decimals?: number;
  ranges: ReferenceRange[];
  sortOrder: number;
}

export interface TestDoc extends Timestamps {
  id: string;
  name: string;
  code: string;
  categoryId: string;
  description?: string;
  sampleType: string;
  containerType?: string;
  sampleVolume?: string;
  collectionInstructions?: string;
  processingInstructions?: string;
  turnaroundHours: number;
  /** Reporting time as printed on the rate list, e.g. "AFTER THREE DAYS". */
  reportingTime?: string;
  price: number;
  discountEligible: boolean;
  active: boolean;
  parameters: TestParameter[];
  /**
   * Per analyzer: the analyzer-side test code, and analyzer result code → parameterId.
   * For single-parameter tests, analyzerTestCode alone maps to that parameter.
   */
  analyzerMappings: Array<{ analyzerId: string; analyzerTestCode: string; parameterCodes: Record<string, string> }>;
  searchTokens: string[];
}

// ─── Orders ──────────────────────────────────────────────────────────────────

export const ORDER_STATUSES = [
  'registered',
  'payment_pending',
  'sample_pending',
  'sample_collected',
  'processing',
  'results_pending',
  'verification_pending',
  'completed',
  'cancelled',
] as const;
export type OrderStatus = (typeof ORDER_STATUSES)[number];

export type Priority = 'routine' | 'urgent' | 'stat';

export interface OrderItem {
  testId: string;
  testName: string;
  testCode: string;
  sampleType: string;
  /** Catalogue / panel price at the time of ordering (snapshot for billing history). */
  unitPrice: number;
  discountEligible: boolean;
  resultId: string;
  sampleId: string;
}

export interface OrderDoc extends Timestamps {
  id: string;
  orderNumber: string;
  patientId: string;
  patientMrNumber: string;
  patientName: string;
  doctorId?: string;
  doctorName?: string;
  panelId?: string;
  technicianId?: string;
  priority: Priority;
  clinicalNotes?: string;
  items: OrderItem[];
  billing: {
    subtotal: number;
    /** Home-collection or other approved fee added to the bill. */
    collectionFee: number;
    discountAmount: number;
    discountReason?: string;
    discountApprovedBy?: AuditActor;
    total: number;
    paid: number;
    refunded: number;
    balance: number;
  };
  status: OrderStatus;
  statusHistory: Array<{ status: OrderStatus; at: string; by: AuditActor; note?: string }>;
  cancellation?: { reason: string; at: string; by: AuditActor };
  homeSamplingRequestId?: string;
  createdBy: AuditActor;
  searchTokens: string[];
}

// ─── Samples ─────────────────────────────────────────────────────────────────

export const SAMPLE_STATUSES = [
  'pending_collection',
  'collected',
  'received',
  'accepted',
  'rejected',
  'processing',
  'completed',
] as const;
export type SampleStatus = (typeof SAMPLE_STATUSES)[number];

export interface SampleDoc extends Timestamps {
  id: string;
  sampleNumber: string; // printed on the barcode
  orderId: string;
  orderNumber: string;
  patientId: string;
  sampleType: string;
  containerType?: string;
  testIds: string[];
  status: SampleStatus;
  collectedAt?: string;
  collectedBy?: AuditActor;
  collectionLocation?: string;
  condition?: string;
  rejectionReason?: string;
  timeline: Array<{ status: SampleStatus; at: string; by: AuditActor; note?: string }>;
}

// ─── Results ─────────────────────────────────────────────────────────────────

export const RESULT_STATUSES = ['pending', 'draft', 'submitted', 'correction_requested', 'approved', 'rejected'] as const;
export type ResultStatus = (typeof RESULT_STATUSES)[number];

export type ResultFlag = 'normal' | 'low' | 'high' | 'critical_low' | 'critical_high' | 'abnormal' | 'no_range';

export interface ResultValue {
  parameterId: string;
  parameterName: string;
  unit?: string;
  value: string;
  numericValue?: number;
  /** Snapshot of the APPROVED range used for flagging, or undefined if none configured. */
  referenceRange?: { low?: number; high?: number; text?: string; rangeId: string };
  flag: ResultFlag;
  source: 'manual' | 'analyzer';
  analyzerMessageId?: string;
}

export interface ResultDoc extends Timestamps {
  id: string;
  orderId: string;
  orderNumber: string;
  patientId: string;
  sampleId: string;
  testId: string;
  testName: string;
  testCode: string;
  status: ResultStatus;
  version: number;
  values: ResultValue[];
  hasCritical: boolean;
  technicianComment?: string;
  approverComment?: string;
  enteredBy?: AuditActor;
  submittedAt?: string;
  approvedBy?: AuditActor;
  approvedAt?: string;
  rejection?: { reason: string; at: string; by: AuditActor; kind: 'rejected' | 'correction_requested' };
  amendment?: { reason: string; at: string; by: AuditActor; previousVersion: number };
  /** True if any value came from an analyzer (still requires human verification). */
  hasAnalyzerValues: boolean;
}

export interface ResultVersionDoc {
  id: string;
  resultId: string;
  version: number;
  snapshot: Omit<ResultDoc, 'id'>;
  approvedBy: AuditActor;
  approvedAt: string;
  supersededAt?: string;
  amendmentReason?: string;
}

// ─── Reports ─────────────────────────────────────────────────────────────────

export interface ReportDoc {
  id: string;
  reportNumber: string;
  orderId: string;
  patientId: string;
  version: number;
  status: 'final' | 'interim' | 'amended' | 'superseded';
  /** Immutable snapshot of everything printed — reprints are byte-for-byte identical. */
  snapshot: ReportSnapshot;
  verificationCode: string;
  generatedBy: AuditActor;
  generatedAt: string;
  supersededBy?: string;
  printCount: number;
}

export interface ReportSnapshot {
  lab: { name: string; tagline: string; address: string; phone: string; email: string; reportFooter?: string; signatories?: ReportSignatory[] };
  patient: { name: string; mrNumber: string; age?: string; gender: Gender; guardian?: string; mobile?: string };
  doctorName?: string;
  orderNumber: string;
  /** Collection centre / branch name and registration time (snapshots from v2 onward). */
  centre?: string;
  registeredAt?: string;
  samples: Array<{ sampleNumber: string; sampleType: string; collectedAt?: string }>;
  tests: Array<{
    resultId: string;
    testName: string;
    testCode: string;
    category: string;
    status: 'approved' | 'pending';
    resultVersion?: number;
    values: Array<{ parameterName: string; value: string; unit?: string; range?: string; flag: ResultFlag }>;
    comment?: string;
    approvedBy?: string;
    approvedAt?: string;
    amended?: boolean;
    amendmentReason?: string;
  }>;
  verifiedBy: string[];
  technicians: string[];
}

// ─── Billing ─────────────────────────────────────────────────────────────────

export type PaymentMethod = 'cash' | 'card' | 'bank_transfer' | 'panel';

export interface PaymentDoc {
  id: string;
  receiptNumber: string;
  orderId: string;
  orderNumber: string;
  patientId: string;
  type: 'payment' | 'refund';
  method: PaymentMethod;
  amount: number;
  reference?: string;
  reason?: string;
  recordedBy: AuditActor;
  recordedAt: string;
  /** Lab-local YYYY-MM-DD, for the daily cash summary. */
  businessDate: string;
}

export interface PanelDoc extends Timestamps {
  id: string;
  name: string;
  type: 'insurance' | 'corporate';
  contactPerson?: string;
  phone?: string;
  email?: string;
  discountPercent: number;
  /** testId → negotiated rate. Overrides catalogue price. */
  rates: Record<string, number>;
  creditLimit?: number;
  active: boolean;
}

// ─── Home sampling ───────────────────────────────────────────────────────────

export type HomeSamplingStatus = 'requested' | 'scheduled' | 'assigned' | 'en_route' | 'collected' | 'cancelled';

export interface HomeSamplingDoc extends Timestamps {
  id: string;
  requestNumber: string;
  patientId?: string;
  patientName: string;
  mobile: string;
  address: string;
  requestedTestIds: string[];
  scheduledFor?: string;
  collectorId?: string;
  collectorName?: string;
  fee: number;
  status: HomeSamplingStatus;
  orderId?: string;
  notes?: string;
  history: Array<{ status: HomeSamplingStatus; at: string; by: AuditActor; note?: string }>;
}

// ─── Inventory ───────────────────────────────────────────────────────────────

export interface InventoryItemDoc extends Timestamps {
  id: string;
  name: string;
  category: 'reagent' | 'chemical' | 'consumable' | 'tube' | 'needle' | 'gloves' | 'equipment_supply' | 'other';
  unit: string;
  quantity: number;
  minimumLevel: number;
  supplier?: string;
  purchasePrice?: number;
  batchNumber?: string;
  expiryDate?: string;
  location?: string;
  active: boolean;
  searchTokens: string[];
}

export interface InventoryTransactionDoc {
  id: string;
  itemId: string;
  itemName: string;
  type: 'receive' | 'consume' | 'adjust' | 'discard';
  quantity: number;
  balanceAfter: number;
  unitPrice?: number;
  batchNumber?: string;
  expiryDate?: string;
  supplier?: string;
  note?: string;
  by: AuditActor;
  at: string;
}

// ─── Analyzers ───────────────────────────────────────────────────────────────

/**
 * connectionState is ONLY ever set from bridge heartbeats. "connected" means a
 * live (non-demo) driver reported an established link within the heartbeat window.
 */
export type AnalyzerConnectionState = 'never_connected' | 'connected' | 'disconnected' | 'error';

export interface AnalyzerDoc extends Timestamps {
  id: string;
  name: string;
  brand: string;
  model?: string;
  serialNumber?: string;
  machineType: string;
  connectionType: 'tcp' | 'serial' | 'file' | 'vendor_api' | 'none';
  host?: string;
  port?: number;
  serialPort?: string;
  baudRate?: number;
  protocol: 'astm' | 'hl7' | 'vendor' | 'unconfirmed';
  /** "demo" = simulated messages, never applied to patient results. */
  mode: 'live' | 'demo';
  enabled: boolean;
  integrationStatus: 'pending_documentation' | 'configured' | 'verified';
  connectionState: AnalyzerConnectionState;
  bridgeId?: string;
  lastHeartbeatAt?: string;
  /** Heartbeat from a DEMO/simulated driver — shown separately, never as "connected". */
  lastDemoHeartbeatAt?: string;
  lastMessageAt?: string;
  lastError?: { at: string; message: string };
  notes?: string;
}

export type AnalyzerMessageStatus = 'received' | 'parse_error' | 'unmatched' | 'matched' | 'applied' | 'duplicate' | 'demo';

export interface AnalyzerMessageDoc {
  id: string;
  analyzerId: string;
  bridgeId: string;
  /** SHA-256 of the raw payload — duplicate detection key. */
  hash: string;
  raw: string;
  protocol: string;
  receivedAt: string;
  isDemo: boolean;
  status: AnalyzerMessageStatus;
  sampleIdentifier?: string;
  results: Array<{ analyzerTestCode: string; value: string; unit?: string; flags?: string }>;
  matchedOrderId?: string;
  matchedSampleId?: string;
  errors: string[];
  matchedBy?: AuditActor;
}

// ─── Notifications / audit / settings ────────────────────────────────────────

export type NotificationKind =
  | 'critical_result'
  | 'pending_verification'
  | 'pending_sample'
  | 'payment'
  | 'low_stock'
  | 'expiring_stock'
  | 'analyzer_error'
  | 'result_rejected';

export interface NotificationDoc {
  id: string;
  kind: NotificationKind;
  severity: 'info' | 'warning' | 'critical';
  /** Deliberately contains no patient names — only order/sample numbers. */
  title: string;
  body: string;
  link?: string;
  /** Visible to holders of this permission. */
  audiencePermission: Permission;
  createdAt: string;
  readBy: string[];
  /** Critical result escalation acknowledgement. */
  acknowledgedBy?: AuditActor;
  acknowledgedAt?: string;
}

export interface AuditLogDoc {
  id: string;
  action: string;
  entity: string;
  entityId?: string;
  actor: AuditActor;
  at: string;
  ip?: string;
  /** Changed fields only; never full medical records. */
  changes?: Record<string, unknown>;
  note?: string;
}

export interface LabSettingsDoc {
  id: 'main';
  name: string;
  tagline: string;
  address: string;
  phone: string;
  email: string;
  website?: string;
  /** Legacy Firebase Storage logo path (read-only fallback for report PDFs). */
  logoPath?: string;
  logo?: MediaRef;
  reportHeaderNote?: string;
  reportFooter?: string;
  /** Consultant pathologists printed on every report (the actual approver is printed separately). */
  reportSignatories?: ReportSignatory[];
  branches: Array<{ id: string; name: string; address?: string; active: boolean }>;
  collectionCenters: Array<{ id: string; name: string; branchId?: string; active: boolean }>;
  patientCategories: string[];
  billing: { maxDiscountPercent: number; currency: string };
  results: { allowSelfVerification: boolean; criticalEscalationMinutes: number };
  barcode: { format: 'CODE128'; labelWidthMm: number; labelHeightMm: number };
  notifications: { lowStock: boolean; expiryDays: number; criticalResults: boolean };
  retention: { auditLogYears: number; reportYears: number };
  updatedAt: string;
  updatedBy?: AuditActor;
}

// ─── Media (Cloudinary) ──────────────────────────────────────────────────────

/**
 * Non-sensitive images only: branding, gallery, staff/doctor portraits and
 * website art. Patient documents and medical reports are NEVER media assets;
 * they stay in private storage and are served only through the API.
 */
export type MediaCategory = 'lab_logo' | 'lab_gallery' | 'staff_profile' | 'doctor_profile' | 'website_illustration';

/** Denormalised pointer kept on the owning document (settings, doctor, user). */
export interface MediaRef {
  assetId: string;
  publicId: string;
  secureUrl: string;
  width?: number;
  height?: number;
}

export interface MediaAssetDoc extends Timestamps {
  id: string;
  category: MediaCategory;
  /** Doctor id or staff uid for profile photos. */
  ownerId?: string;
  provider: 'cloudinary';
  publicId: string;
  secureUrl: string;
  version: number;
  format: string;
  width: number;
  height: number;
  bytes: number;
  originalName: string;
  alt?: string;
  uploadedBy: AuditActor;
}

/** Compact, single-document view of the whole test catalogue (prices, samples, reporting times). */
export interface CatalogIndexDoc {
  id: 'main';
  updatedAt: string;
  categories: Array<{ id: string; name: string; sortOrder: number; active: boolean }>;
  tests: Array<{ id: string; code: string; name: string; categoryId: string; price: number; sampleType: string; containerType?: string; turnaroundHours: number; reportingTime?: string; discountEligible: boolean; active: boolean }>;
}

export interface ReportSignatory {
  name: string;
  qualification?: string;
  title?: string;
}
